WITH with_windows AS (SELECT id, dept_id, level, SUM(salary) OVER (ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary, ROW_NUMBER() OVER w_part AS event_seq, ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY hire_date, id) AS seq_no, LAST_VALUE(level, TRUE) OVER (PARTITION BY manager_id, dept_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_level, AVG(salary) OVER (PARTITION BY manager_id ORDER BY salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS salary_avg_3 FROM employees WINDOW w_part AS (PARTITION BY dept_id ORDER BY salary DESC, id)) SELECT id, dept_id, level, cumulative_salary, event_seq, seq_no, last_known_level, salary_avg_3 FROM with_windows;
